CREATE TABLE IF NOT EXISTS offices(id INTEGER PRIMARY KEY AUTOINCREMENT,code VARCHAR(20) NOT NULL UNIQUE,name VARCHAR(160) NOT NULL,head VARCHAR(160),supervisor VARCHAR(160),contact VARCHAR(160),status VARCHAR(30) NOT NULL DEFAULT 'Active');
CREATE TABLE IF NOT EXISTS users(id INTEGER PRIMARY KEY AUTOINCREMENT,full_name VARCHAR(160) NOT NULL,email VARCHAR(190) NOT NULL UNIQUE,password_hash VARCHAR(255) NOT NULL,role VARCHAR(40) NOT NULL,office_id INTEGER NOT NULL REFERENCES offices(id),position VARCHAR(160),status VARCHAR(30) DEFAULT 'Active');
CREATE TABLE IF NOT EXISTS vehicles(id INTEGER PRIMARY KEY AUTOINCREMENT,model VARCHAR(160) NOT NULL,type VARCHAR(40) NOT NULL,plate VARCHAR(40) NOT NULL UNIQUE,property_number VARCHAR(80),capacity INTEGER NOT NULL,odometer INTEGER NOT NULL DEFAULT 0,registration_expiry DATE,condition_text VARCHAR(160),status VARCHAR(40) NOT NULL,photo_url VARCHAR(255));
CREATE TABLE IF NOT EXISTS drivers(id INTEGER PRIMARY KEY AUTOINCREMENT,full_name VARCHAR(160) NOT NULL,employee_number VARCHAR(80) NOT NULL UNIQUE,office_id INTEGER REFERENCES offices(id),contact VARCHAR(80),license_number VARCHAR(80),license_expiry DATE NOT NULL,status VARCHAR(40) NOT NULL);
CREATE TABLE IF NOT EXISTS requisitions(id INTEGER PRIMARY KEY AUTOINCREMENT,reference VARCHAR(40) UNIQUE,requester_id INTEGER NOT NULL REFERENCES users(id),office_id INTEGER NOT NULL REFERENCES offices(id),vehicle_type VARCHAR(40) NOT NULL,vehicle_id INTEGER REFERENCES vehicles(id),driver_id INTEGER REFERENCES drivers(id),preferred_driver VARCHAR(160),passengers TEXT NOT NULL,start_datetime DATETIME NOT NULL,end_datetime DATETIME NOT NULL,destination VARCHAR(255) NOT NULL,purpose TEXT NOT NULL,fuel_allocation INTEGER DEFAULT 0,fuel_quantity DECIMAL(10,2) DEFAULT 0,fuel_remarks TEXT,status VARCHAR(50) NOT NULL,created_at DATETIME NOT NULL);
CREATE INDEX IF NOT EXISTS idx_schedule ON requisitions(vehicle_id,status,start_datetime,end_datetime);
CREATE INDEX IF NOT EXISTS idx_driver_schedule ON requisitions(driver_id,status,start_datetime,end_datetime);
CREATE TABLE IF NOT EXISTS approvals(id INTEGER PRIMARY KEY AUTOINCREMENT,requisition_id INTEGER NOT NULL REFERENCES requisitions(id),user_id INTEGER NOT NULL REFERENCES users(id),stage VARCHAR(40) NOT NULL,decision VARCHAR(40) NOT NULL,remarks TEXT,created_at DATETIME NOT NULL);
CREATE TABLE IF NOT EXISTS vehicle_movements(id INTEGER PRIMARY KEY AUTOINCREMENT,requisition_id INTEGER NOT NULL UNIQUE REFERENCES requisitions(id),departure DATETIME NOT NULL,return_time DATETIME,odometer_out INTEGER NOT NULL,odometer_in INTEGER,condition_text VARCHAR(160),remarks TEXT,checked_by INTEGER REFERENCES users(id));
CREATE TABLE IF NOT EXISTS vehicle_blocks(id INTEGER PRIMARY KEY AUTOINCREMENT,vehicle_id INTEGER NOT NULL REFERENCES vehicles(id),start_datetime DATETIME NOT NULL,end_datetime DATETIME NOT NULL,reason TEXT NOT NULL,created_by INTEGER REFERENCES users(id));
CREATE TABLE IF NOT EXISTS notifications(id INTEGER PRIMARY KEY AUTOINCREMENT,user_id INTEGER NOT NULL REFERENCES users(id),message TEXT NOT NULL,requisition_id INTEGER REFERENCES requisitions(id),is_read INTEGER DEFAULT 0,created_at DATETIME NOT NULL);
CREATE TABLE IF NOT EXISTS audit_logs(id INTEGER PRIMARY KEY AUTOINCREMENT,user_id INTEGER REFERENCES users(id),action VARCHAR(100) NOT NULL,details TEXT,created_at DATETIME NOT NULL);
CREATE TABLE IF NOT EXISTS print_logs(id INTEGER PRIMARY KEY AUTOINCREMENT,requisition_id INTEGER REFERENCES requisitions(id),user_id INTEGER REFERENCES users(id),created_at DATETIME NOT NULL);
CREATE TABLE IF NOT EXISTS system_settings(setting_key VARCHAR(80) PRIMARY KEY,setting_value TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS login_attempts(id INTEGER PRIMARY KEY AUTOINCREMENT,identity_hash VARCHAR(64) NOT NULL,attempted_at DATETIME NOT NULL);
